var e=JSON.parse(`"<h4>Позиционирование осей обрабатывающих центров (ГОСТ ISO 10791-4-2017)</h4>\\n<p><b>Центры обрабатывающие. Часть 4. Точность и повторяемость позиционирования линейных осей и осей вращения.</b> Все 4 таблицы стандарта (таблицы 1—4) полностью, разделы 3 (3.1—3.5), 4 (4.1—4.4), 5 (5.1—5.4), 6 (6.1—6.3), а также поправки (титульный лист — ИУС 4—2019; предисловие — ИУС 3—2022, дата введения 2021-10-12). Подбор и расчёт — в приложении.</p>\\n<p><b>Таблица 1 — Допуски позиционирования для осей до 2000 мм</b> (единицы: мм)</p>\\n<div class=\\"hb-table\\"><table><thead><tr><th rowspan=\\"2\\">Допуски, мм</th><th colspan=\\"4\\">Измерительный ход оси, мм</th></tr><tr><th>≤500</th><th>>500≤800</th><th>>800≤1250</th><th>>1250≤2000</th></tr></thead><tbody>\\n<tr><td>Двунаправленная точность позиционирования A</td><td>0,022</td><td>0,025</td><td>0,032</td><td>0,042</td></tr>\\n<tr><td>Однонаправленная точность позиционирования A↑ и A↓</td><td>0,016</td><td>0,020</td><td>0,025</td><td>0,030</td></tr>\\n<tr><td>Двунаправленная повторяемость позиционирования R</td><td>0,012</td><td>0,015</td><td>0,018</td><td>0,020</td></tr>\\n<tr><td>Однонаправленная повторяемость позиционирования R↑ и R↓</td><td>0,006</td><td>0,008</td><td>0,010</td><td>0,013</td></tr>\\n<tr><td>Разность погрешностей позиционирования B</td><td>0,010</td><td>0,010</td><td>0,012</td><td>0,012</td></tr>\\n<tr><td>Средняя разность погрешностей позиционирования B̄</td><td>0,006</td><td>0,006</td><td>0,008</td><td>0,008</td></tr>\\n<tr><td>Двунаправленное систематическое позиционное отклонение E</td><td>0,015</td><td>0,018</td><td>0,023</td><td>0,030</td></tr>\\n<tr><td>Однонаправленное систематическое позиционное отклонение E↑ и E↓</td><td>0,010</td><td>0,012</td><td>0,015</td><td>0,018</td></tr>\\n<tr><td>Диапазон среднего двунаправленного позиционного отклонения M</td><td>0,010</td><td>0,012</td><td>0,015</td><td>0,020</td></tr></tbody></table></div>\\n<p><b>Таблица 2 — Формат представления результатов полной проверки до 2000 мм</b> (единицы: мм)</p>\\n<div class=\\"hb-table\\"><table><thead><tr><th>Результаты, мм</th><th>Обозначение оси и соответствующий ход, мм (четыре пустых подграфа)</th></tr></thead><tbody>\\n<tr><td>Двунаправленная точность позиционирования</td><td>A</td></tr>\\n<tr><td>Точность позиционирования (положительная)</td><td>A↑</td></tr>\\n<tr><td>Точность позиционирования (отрицательная)</td><td>A↓</td></tr>\\n<tr><td>Двунаправленная повторяемость позиционирования</td><td>R</td></tr>\\n<tr><td>Повторяемость позиционирования (положительная)</td><td>R↑</td></tr>\\n<tr><td>Повторяемость позиционирования (отрицательная)</td><td>R↓</td></tr>\\n<tr><td>Разность погрешностей позиционирования</td><td>B</td></tr>\\n<tr><td>Средняя разность погрешностей позиционирования</td><td>B̄</td></tr>\\n<tr><td>Двунаправленное систематическое позиционное отклонение</td><td>E</td></tr>\\n<tr><td>Систематическое позиционное отклонение (положительное)</td><td>E↑</td></tr>\\n<tr><td>Систематическое позиционное отклонение (отрицательное)</td><td>E↓</td></tr>\\n<tr><td>Диапазон среднего двунаправленного позиционного отклонения</td><td>M</td></tr></tbody></table></div>\\n<p><b>Таблица 3 — Допуски позиционирования для осей до 360°</b> (единицы: угловые секунды)</p>\\n<div class=\\"hb-table\\"><table><thead><tr><th colspan=\\"2\\">Допуски, угловые секунды</th></tr></thead><tbody>\\n<tr><td>Двунаправленная точность позиционирования A</td><td>28</td></tr>\\n<tr><td>Однонаправленная точность позиционирования A↑ и A↓</td><td>22</td></tr>\\n<tr><td>Двунаправленная повторяемость позиционирования R</td><td>16</td></tr>\\n<tr><td>Однонаправленная повторяемость позиционирования R↑ и R↓</td><td>8</td></tr>\\n<tr><td>Разность погрешностей позиционирования B</td><td>12</td></tr>\\n<tr><td>Средняя разность погрешностей позиционирования B̄</td><td>8</td></tr>\\n<tr><td>Двунаправленное систематическое позиционное отклонение E</td><td>20</td></tr>\\n<tr><td>Однонаправленное систематическое позиционное отклонение E↑ и E↓</td><td>14</td></tr>\\n<tr><td>Диапазон среднего двунаправленного позиционного отклонения M</td><td>12</td></tr></tbody></table></div>\\n<p><b>Таблица 4 — Формат представления результатов полной проверки до 360°</b> (единицы: угловые секунды)</p>\\n<div class=\\"hb-table\\"><table><thead><tr><th>Результаты, угловые секунды</th><th>Обозначение оси</th></tr></thead><tbody>\\n<tr><td>Двунаправленная точность позиционирования</td><td>A</td></tr>\\n<tr><td>Точность позиционирования (положительная)</td><td>A↑</td></tr>\\n<tr><td>Точность позиционирования (отрицательная)</td><td>A↓</td></tr>\\n<tr><td>Двунаправленная повторяемость позиционирования</td><td>R</td></tr>\\n<tr><td>Повторяемость позиционирования (положительная)</td><td>R↑</td></tr>\\n<tr><td>Повторяемость позиционирования (отрицательная)</td><td>R↓</td></tr>\\n<tr><td>Разность погрешностей позиционирования</td><td>B</td></tr>\\n<tr><td>Средняя разность погрешностей позиционирования</td><td>B̄</td></tr>\\n<tr><td>Двунаправленное систематическое позиционное отклонение</td><td>E</td></tr>\\n<tr><td>Систематическое позиционное отклонение (положительное)</td><td>E↑</td></tr>\\n<tr><td>Систематическое позиционное отклонение (отрицательное)</td><td>E↓</td></tr>\\n<tr><td>Диапазон среднего двунаправленного позиционного отклонения</td><td>M</td></tr></tbody></table></div>\\n<p><b>Требования и указания стандарта (16).</b></p>\\n<div class=\\"hb-table\\"><table><thead><tr><th>Пункт</th><th>Содержание</th></tr></thead><tbody>\\n<tr><td>3.1</td><td>Все линейные размеры, отклонения и соответствующие допуски выражены в миллиметрах; угловые размеры — в градусах, угловые отклонения и допуски — в угловых секундах. Выражение для преобразования: 0,010/1000 = 10 мкрад (мкрад — микрорадиан) ≈ 2″.</td></tr>\\n<tr><td>3.2</td><td>Следует руководствоваться требованиями ISO 230-1, особенно при установке станка перед испытанием, прогреве, описании методов измерения, оценке и представлении результатов.</td></tr>\\n<tr><td>3.3</td><td>Последовательность испытаний, указанная в стандарте, не обязательна для практического применения; для упрощения установки и настройки средств измерения допускается проводить испытания в любой последовательности.</td></tr>\\n<tr><td>3.4</td><td>При испытаниях не всегда есть необходимость или возможность проведения всех проверок. Если испытания требуются для приёмки, выбор видов испытаний оставляется на усмотрение пользователя по согласованию с поставщиком/изготовителем. Перечень видов испытаний должен быть чётко установлен при заказе станка. Простые ссылки на стандарт без установленного и согласованного перечня и без соглашения по издержкам не могут считаться частью контракта.</td></tr>\\n<tr><td>3.5</td><td>Во время проверки оси те из трёх основных линейных осей, которые не используются в испытаниях, должны находиться, насколько возможно, в середине своего рабочего хода или в ином положении, минимизирующем прогибы элементов, влияющих на результаты измерений. Выдвижной шпиндель, подвижный хобот и т. д., когда они являются дополнительными осями, должны находиться в исходном положении.</td></tr>\\n<tr><td>4.1</td><td>В таблице 1 приведены допуски позиционирования (определение — п. 2 ISO 230-2) для обрабатывающих центров нормальной точности при измерительном ходе до 2000 мм. Кроме того, должно быть обеспечено графическое представление результатов, как указано в ISO 230-2.</td></tr>\\n<tr><td>4.2</td><td>Может быть использован лазерный интерферометр или другая измерительная система с сопоставимой точностью (см. 5.1 ISO 230-1).</td></tr>\\n<tr><td>4.3</td><td>При использовании лазерного интерферометра — меры предосторожности по ISO 230-1 (подраздел А.13 приложения А). Процедуры испытания — по ISO 230-2, в особенности 4.3.2 для полной проверки до 2000 мм.</td></tr>\\n<tr><td>4.4</td><td>В таблице 2 — пример формата представления результатов статистического анализа; обязательно графическое представление результатов, как указано в ISO 230-2.</td></tr>\\n<tr><td>5.1</td><td>В таблице 3 — допуски позиционирования (определение — ISO 230-2, раздел 2) для обрабатывающих центров нормальной точности при измерительном ходе до 360°.</td></tr>\\n<tr><td>5.2</td><td>Может быть использован лазерный угловой интерферометр с делительным столом, автоколлиматор с многогранным зеркалом или другая измерительная система с сопоставимой точностью.</td></tr>\\n<tr><td>5.3</td><td>При использовании автоколлиматора — меры предосторожности по А.11 ISO 230-1. Процедуры — по ISO 230-2, в особенности пункт 4.3.4 для полной проверки до 360°.</td></tr>\\n<tr><td>5.4</td><td>В таблице 4 — пример формата представления результатов; обязательно графическое представление, как указано в ISO 230-2.</td></tr>\\n<tr><td>6.1</td><td>Данные идентификации машины: a) идентификационные данные машины; b) название компании изготовителя; c) год выпуска, при наличии; d) тип и серийный номер; e) конфигурация машины в соответствии с 3.9 или 3.10 ISO 10791-1, ISO 10791-2 и ISO 10791-3, если возможно.</td></tr>\\n<tr><td>6.2</td><td>Данные идентификации испытания: a) дата и место проведения испытания; b) компания и имя инспектора; c) перечень используемого испытательного оборудования, включая имя производителя, тип и серийный номер компонентов (например, лазерная головка, оптика, датчики температуры).</td></tr>\\n<tr><td>6.3</td><td>Данные по условиям испытаний: a) компоненты машины, движущиеся вдоль или вокруг оси при испытании; b) скорость подачи; c) положения осевых салазок или движущихся компонентов по осям, не участвующим в испытании; d) положение линии измерения; e) количество и положение датчиков температуры; f) показания датчиков температуры непосредственно до и после испытания; g) используемый коэффициент для материальной компенсации; h) при необходимости температура воздуха, давление и влажность непосредственно до и после испытания; i) тип компенсации, применяемый к осям машины; j) тип компенсации, применяемый к данным измерений.</td></tr></tbody></table></div>\\n<p><b>Формулы, обозначения и пояснения:</b></p>\\n<ul>\\n<li>0,010/1000 = 10 мкрад (μrad — микрорадиан) ≈ 2″ — выражение для преобразования угловых отклонений или допусков.</li>\\n<li>Обозначения: A — двунаправленная точность позиционирования; A↑ и A↓ — однонаправленная точность; R — двунаправленная повторяемость; R↑ и R↓ — однонаправленная повторяемость; B — разность погрешностей позиционирования; B̄ — средняя разность погрешностей позиционирования; E — двунаправленное систематическое позиционное отклонение; E↑ и E↓ — однонаправленное систематическое; M — диапазон среднего двунаправленного позиционного отклонения.</li>\\n</ul>\\n<div class=\\"hb-note\\"><b>Спорные места (как напечатано):</b><ul>\\n<li>Дата введения: приказ Росстандарта от 7 ноября 2018 г. № 938-ст, введён с 1 марта 2019 г.; издание (октябрь 2020 г.) с поправкой (ИУС 4—2019); отдельной поправкой введена дата 2021-10-12 (ИУС 3—2022). В карточке stroyinf — 14.03.2022. Расхождение не сглажено.</li>\\n<li>Обозначение B̄: черта над B тонкая; в таблицах 1, 3 и форматах 2, 4 читается как B с чертой (средняя разность), в отличие от B без черты.</li>\\n<li>Ссылка 4.3 на «ISO 230-2, в особенности 4.3.2» и 5.3 на «пункт 4.3.4» — в ISO 230-2-2016 пункты с такими номерами относятся к 4.3.2/4.3.4 ISO 230-2:2014; сохранено как напечатано.</li>\\n</ul></div>\\n"`);export{e as default};